  function filtered(){return cards;}
  function renderCards(){const list=$('casesList');if(!list)return;const rows=filtered(),pending=cards.filter(x=>x.status==='pending_review'||x.status==='needs_clarification').length;$('casesPending').textContent=t('pendingCount',{count:pending});$('supportCasesPending').textContent=String(pending);$('supportCasesPending').hidden=!pending;const empty=batchId&&terminalBatch()&&!$('casesStatus').value?t('batchNone',{count:batchState.message_count??0}):t('empty');list.innerHTML=rows.length?rows.map(card=>`<article class="support-case"><div><span class="badge" data-case-status="${esc(card.status)}">${esc(t(card.status==='approved'?'approved':card.status==='rejected'?'rejected':card.status==='needs_clarification'?'clarify':'pending'))}</span><h2>${esc(card.title||'—')}</h2><p>${esc((card.symptoms||[]).join(' · ')||'—')}</p><small>${esc(sourceKind(card))} · ${esc(stamp(card.updated_at||card.created_at))}</small></div><button class="outline" type="button" data-case-open="${esc(card.id)}">${t('open')}</button></article>`).join(''):`<div class="empty">${esc(empty)}</div>`;list.querySelectorAll('[data-case-open]').forEach(button=>button.onclick=()=>openCard(button.dataset.caseOpen));$('casesLimit').textContent=nextBefore?t('limited'):'';$('casesMore').hidden=!nextBefore;}
  async function load(append=false){const version=++generation;const query=new URLSearchParams({...expected(),limit:50});for(const [key,id] of [['channel_id','casesChannel'],['conversation_id','casesConversation'],['status','casesStatus']]){if($(id).value)query.set(key,$(id).value);}if(batchId)query.set('batch_id',batchId);if(append&&nextBefore)query.set('before',nextBefore);notice(t('loading'));try{const result=await api(base+'?'+query);if(version!==generation)return null;cards=append?cards.concat(result.candidates||[]):result.candidates||[];nextBefore=result.next_before||null;notice('');renderCards();return result;}catch(error){if(version!==generation)return null;notice(error.status===403?t('noAccess'):error.message);return null;}}
