  async function analyse(){const channel=$('casesChannel').value,from=$('casesFrom').value,to=$('casesTo').value;if(!channel||!from||!to){notice(t('period'));return;}const start=new Date(from+'T00:00:00'),end=new Date(to+'T00:00:00');end.setDate(end.getDate()+1);if(end<=start||end-start>31*86400000){notice(t('period'));return;}const params={language:'az',channel_id:channel,period_start:start.toISOString(),period_end:end.toISOString(),history_mode:$('casesUnified').checked?'unified_group':'channel'};if($('casesConversation').value)params.conversation_id=$('casesConversation').value;const signature=JSON.stringify({...expected(),...params});if(batchRequest?.signature!==signature)batchRequest={signature,id:crypto.randomUUID()};$('casesAnalyse').disabled=true;try{await showBatch(await api(base+'/batches',{method:'POST',body:JSON.stringify({...expected(),...params,request_id:batchRequest.id})}));}catch(error){notice(error.message);$('casesAnalyse').disabled=false;}}
