      if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.error||'Faylı açmaq mümkün olmadı.');}
      const blob=await response.blob();if(blob.size<=0||blob.size>20*1024*1024)throw new Error('Faylın ölçüsü açmaq üçün uyğun deyil.');
